steps.script:
var m = SecondaryMissionManager._player_state["2"]["active"][0]
var guards = m["mission_data"].get("guards", {})
var units = GameState.state.get("units", {})
for obj_id in guards:
	var u = units.get(str(guards[obj_id]), {})
	if u.is_empty() or int(u.get("owner", 0)) != 2:
		return false
return true

var rows = tree.root.get_node_or_null("GuardSelectionDialog/Content/ObjectiveScroll/ObjectiveRows")
if rows == null:
	return -1
var blank := 0
for row in rows.get_children():
	for child in row.get_children():
		if child is OptionButton:
			if child.selected <= 0:
				blank += 1
return blank

var rows = tree.root.get_node_or_null("GuardSelectionDialog/Content/ObjectiveScroll/ObjectiveRows")
var filled := 0
for row in rows.get_children():
	for child in row.get_children():
		if child is OptionButton and child.selected > 0:
			filled += 1
return filled > 0
